'use strict';
(()=>{
const $=id=>document.getElementById(id);if(!$('forecast'))return;
const names=['januar','februar','mars','april','mai','juni','juli','august','september','oktober','november','desember'];
const month=s=>names[+s.slice(5)-1]+' '+s.slice(0,4),range=(a,b)=>month(a)+' – '+month(b);
const num=n=>n.toLocaleString('nb-NO',{maximumFractionDigits:0}),percent=n=>(100*n).toLocaleString('nb-NO',{maximumFractionDigits:1})+' %',signed=n=>(n>=0?'+':'−')+percent(Math.abs(n));
const today=()=>new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Oslo',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
let latest=null,lastDay='';
function card(c,f){
 const p=c.prediction;if(!p)return '<article class="panel"><h3>'+range(c.targetStart,c.targetEnd)+'</h3><p>For få historiske forløp til å beregne et anslag.</p></article>';
 const t=c.threshold,b=c.backtest,opposite=f.usedAnomaly>=0?'tørrere':'våtere',condition=f.usedAnomaly>=0?'over':'under';
 const skill=b.n?`${num(Math.abs(b.skill)*100)} % ${b.skill>0?'lavere':'høyere'} feil enn sesongmodellen`:'For lite grunnlag til historisk test';
 const status=b.n<20?'For få historiske testår':b.skill>0?'Litt bedre mengdeanslag i testen':'Slår ikke sesongmodellen på mengde';
 return `<article class="panel forecast-card"><div class="forecast-card-top"><p class="eyebrow">${c.wait?'ETTER TRE VENTEMÅNEDER':'NESTE TRE MÅNEDER'}</p><span class="forecast-tag">${f.scenario?'Scenario':'Eksperimentelt anslag'}</span></div><h3>${range(c.targetStart,c.targetEnd)}</h3><div class="forecast-amount">${num(p.mm)} <span>mm</span></div><p class="forecast-versus"><strong class="${p.anomaly>=0?'positive':'negative'}">${signed(p.anomaly)}</strong> mot sesongsnitt ${num(c.normal)} mm</p><div class="forecast-probabilities"><div><span>Modellanslag · tørrere</span><strong>${percent(p.dry)}</strong></div><div><span>Våtere eller likt</span><strong>${percent(1-p.dry)}</strong></div></div><p class="forecast-range">Historisk 10.–90. persentil: <strong>${num(p.lowMm)}–${num(p.highMm)} mm</strong><br><span>Et bredt spenn av mulige utfall, ikke et løfte om 80 % dekning.</span></p><div class="forecast-status ${b.skill>0?'':'uncertain'}">${status}<small>${skill} · ${b.n} testår</small></div><div class="table-wrap"><table class="forecast-months"><thead><tr><th>Måned</th><th>Sesongsnitt</th><th>Anslag</th></tr></thead><tbody>${p.months.map(m=>`<tr><td>${month(m.month)}</td><td>${num(m.normal)} mm</td><td><strong>${num(m.predicted)} mm</strong></td></tr>`).join('')}</tbody></table></div><p class="small muted">Månedsfordelingen følger normalen. Dette er ett samlet sesonganslag, ikke tre uavhengige månedsvarsler.</p>
 <details><summary>Din ${num(t.value*100)} %-regel · ${t.n} historiske treff</summary><p>Siste seks måneder minst ${num(t.value*100)} % ${condition} sitt daværende snitt, med samme kalendermåneder og ${c.lead} hele måneder mellom dataperioden og utfallet.</p>${t.n?`<p><strong>${t.opposite} av ${t.n} (${percent(t.probability)})</strong> fikk en ${opposite} periode. Omtrentlig 95 % Wilson-intervall: ${percent(t.interval[0])}–${percent(t.interval[1])}.</p><p>Gjennomsnittlig avvik etterpå, med <strong>alle utfall</strong> inkludert: ${signed(t.meanAnomaly)}. Det tilsvarer <strong>${num(c.normal*(1+t.meanAnomaly))} mm</strong> for ${range(c.targetStart,c.targetEnd)}. Dette er den rene terskelregelen, før modellens demping.</p>${Math.abs(f.usedAnomaly)<t.value?'<p class="forecast-caution">Det valgte seksmånedersavviket oppfyller ikke terskelen. Denne frekvensen gjelder derfor ikke direkte for dagens situasjon.</p>':''}<div class="table-wrap"><table><thead><tr><th>Vindu med seks måneder</th><th>Avvik</th><th>Utfallsperiode</th><th>Avvik etterpå</th></tr></thead><tbody>${t.years.map(r=>`<tr><td>${range(r.start,r.end)}</td><td>${signed(r.input)}</td><td>${range(r.targetStart,r.targetEnd)}</td><td>${signed(r.outcome)}</td></tr>`).join('')}</tbody></table></div>`:'<p>Ingen treff. Ingen sannsynlighet kan beregnes ved denne terskelen.</p>'}<p class="small muted">En høy treffandel fra få år er ikke en bekreftet prognosesannsynlighet. Bytte av sesong, ventetid eller normalgrunnlag kan endre resultatet mye.</p></details>
 <details><summary>Slik er anslaget beregnet og testet</summary><p>${c.n} avsluttede historiske forløp med samme kalenderplassering. De 20 mest lignende seksmånedersavvikene vektes etter avstand til ${signed(f.usedAnomaly)}. Effekten dempes mot vanlig sesonghistorikk for å unngå store utslag fra få treff.</p><p><strong>Regnestykket:</strong> ${num(c.normal)} mm × (1 ${p.anomaly>=0?'+':'−'} ${Math.abs(p.anomaly).toFixed(3)}) ≈ ${num(p.mm)} mm. Snittet er ${f.normalStart}–${f.normalEnd}.</p>${b.n?`<p>Årlig, fremoverskuende test ${b.first.slice(0,4)}–${b.last.slice(0,4)}: hver prognose er laget kun fra forløp som var avsluttet da. Gjennomsnittlig absolutt feil: <strong>${num(b.mae)} mm</strong>, mot ${num(b.baselineMae)} mm for sesongmodellen og ${num(b.normalMae)} mm for rent 30-årssnitt.</p><p>Brier-score for tørr periode: ${b.brier.toFixed(3)} mot ${b.baselineBrier.toFixed(3)} for sesongmodellen (lavere er bedre). Det viste historiske spennet inneholdt faktisk utfall i ${percent(b.coverage)} av testårene.</p>`:''}<p class="small muted">Dette er en første modelltest, ikke uavhengig dokumentasjon etter modellutviklingen. Stasjonsbytter, datakvalitet, klimaendringer og få år gjør prognosen usikker. En god testhistorikk gir ingen garanti for neste sesong.</p></details></article>`;
}
function render(){
 lastDay=today();const scenario=$('forecastScenario').checked?Number($('forecastAnomaly').value)/100:null;
 $('forecastAnomaly').disabled=scenario===null;$('forecastAnomalyValue').textContent=signed(Number($('forecastAnomaly').value)/100);$('forecastThresholdValue').textContent=$('forecastThreshold').value+' %';
 try{const result=window.RainForecast.create(window.RAIN_DATA).forecast({asOf:lastDay,alignment:$('forecastAlignment').value,scenario,threshold:Number($('forecastThreshold').value)/100});latest=result;
 if(!result.available){$('forecastCards').innerHTML='<p>'+result.reason+'</p>';$('forecastInput').textContent=result.reason;return}
 const f=result;$('forecastInput').innerHTML=`<div><span>Seks siste hele måneder</span><strong>${range(f.sourceStart,f.sourceEnd)}</strong></div><div><span>Målt / normalt</span><strong>${num(f.sourceActual)} / ${num(f.sourceNormal)} mm</strong></div><div><span>Faktisk avvik</span><strong class="${f.sourceAnomaly>=0?'positive':'negative'}">${signed(f.sourceAnomaly)}</strong></div>`;
 $('forecastTiming').textContent=(f.alignment==='calendar'?'Kalenderstyrt: de neste hele månedene, deretter tre måneders ventetid. ':'Datastyrt: prognosen starter etter siste komplette datamåned. ')+`Dataperioden slutter ${month(f.sourceEnd)}. Det er ${f.cards[1].lead} hele måneder mellom dataperioden og den utsatte prognosen.`+(f.missingMonths>0?` Datagrunnlaget mangler ${f.missingMonths} nyere, avsluttede måneder.`:'')+' Pågående måned brukes ikke som om den var komplett.';
 $('forecastScenarioNotice').hidden=!f.scenario;$('forecastScenarioNotice').textContent=`SCENARIO: anslaget bruker ${signed(f.usedAnomaly)} i stedet for målt ${signed(f.sourceAnomaly)}. Dette er ikke dagens prognose.`;
 $('forecastCards').innerHTML=f.cards.map(c=>card(c,f)).join('');$('forecastIssued').textContent='Beregnet '+lastDay.split('-').reverse().join('.')+' · målegrunnlag til '+month(f.sourceEnd);
 }catch(e){$('forecastCards').textContent='Prognosen kunne ikke beregnes. Kontroller at måleserien er komplett.';console.error(e)}
}
['forecastAlignment','forecastScenario','forecastAnomaly','forecastThreshold'].forEach(id=>$(id).addEventListener('change',render));
$('forecastAnomaly').addEventListener('input',()=>{$('forecastAnomalyValue').textContent=signed(Number($('forecastAnomaly').value)/100)});
$('forecastThreshold').addEventListener('input',()=>{$('forecastThresholdValue').textContent=$('forecastThreshold').value+' %'});
$('forecastDownload').onclick=()=>{if(!latest?.available)return;const body=JSON.stringify(latest,null,2),blob=new Blob([body],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='regnrytme-'+(window.RAIN_CITY?.id||'bergen')+'-prognose-'+latest.asOf+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
window.addEventListener('frost-updated',render);window.addEventListener('pageshow',()=>{if(today()!==lastDay)render()});document.addEventListener('visibilitychange',()=>{if(!document.hidden&&today()!==lastDay)render()});render();
})();
